/* @socom-skeleton stub SetMidClip__Q23zdb7CCameraFf */
void zdb::CCamera::SetMidClip(float mid)
{
	/* 0x1e5420: a mid plane beyond the far plane pushes the far plane (and the guard band) out */
	m_mid_plane = mid;

	if (!(mid <= m_far_plane))
	{
		m_far_plane = mid;
		m_guardBand_max[3] = mid;
	}
}

